#include <bits/stdc++.h>
using namespace std;

// Type aliases for speed
using ll = long long;
using vi = vector<int>;
using vll = vector<ll>;

// Macros for common operations
#define pb push_back
#define all(x) (x).begin(), (x).end()
#define FOR(i, a, b) for (int i = (a); i < (b); ++i)

void solve() {
    int n;
    cin >> n;
    vi a(n);
    FOR(i, 0, n) cin >> a[i];

    sort(all(a));
    cout << a.back() << "\n";
}

int main() {
    // FAST I/O
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t = 1;
    cin >> t; // Read number of test cases
    while (t--) {
        solve();
    }
    return 0;
}
